export function parseOpenCustodyVaultInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedOpenCustodyVaultInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      adminRecord: getNextAccount(),
      shareClass: getNextAccount(),
      mint: getNextAccount(),
      custodyVault: getNextAccount(),
      escrow: getNextAccount(),
      escrowMarker: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      platform: getNextAccount(),
    },
    data: getOpenCustodyVaultInstructionDataDecoder().decode(instruction.data),
  };
}
